def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    remaining = 100 - n
    if remaining <= 3:
        return 'D'
    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s
    opp_d_streak = streak(opp, 'D')
    my_d_streak = streak(me, 'D')
    opp_def = 0
    for x in opp:
        if x == 'D':
            opp_def += 1
    opp_rate = opp_def / float(n)
    if opp_d_streak >= 3:
        if my_d_streak >= 2 and rng.random() < 0.15:
            return 'C'
        return 'D'
    if opp_d_streak == 2:
        return 'D'
    if last_opp == 'D':
        if opp_rate > 0.45:
            return 'D'
        if my_d_streak >= 1 and rng.random() < 0.5:
            return 'C'
        return 'D'
    if opp_rate > 0.65:
        if rng.random() < 0.1:
            return 'C'
        return 'D'
    if opp_rate > 0.35:
        if rng.random() < 0.25:
            return 'D'
        return 'C'
    if remaining <= 10:
        return 'D'
    if n > 20 and opp_rate < 0.1:
        if rng.random() < 0.06:
            return 'D'
        return 'C'
    if rng.random() < 0.03:
        return 'D'
    return 'C'
